have h1 : 1 / a + 1 / b = (a + b) / (a * b) := one_div_add_one_div ha hb
rw [h1]
have h2 : (a + b) * (a + b) / (a * b) ≥ 4 :=
  let h3 : (a + b)^2 / (a * b) ≥ 4 :=
    let h4 : (a + b)^2 ≥ 4 * a * b :=
      let h5 : (a + b)^2 - 4 * a * b ≥ 0 :=
        let h6 : a^2 + 2 * a * b + b^2 - 4 * a * b ≥ 0 :=
          let h7 : a^2 - 2 * a * b + b^2 ≥ 0 :=
            let h8 : (a - b)^2 ≥ 0 :=
              Real.pow_two_nonneg (a - b)
            exact h8
          exact h7
        exact h6
      exact h4
    exact h3
exact h2

rw [one_div_add_one_div ha hb]
rw [mul_assoc]
have h : (a + b) * (a + b) / (a * b) ≥ 4
  := by {
    rw [mul_comm (a * b) (a + b)]
    have h1 : (a + b) * (a + b) ≥ 4 * (a * b)
      := by {
        apply Real.mul_self_le_add_two_mul_add_mul_self ha hb
      }
    rw [mul_right_inj' (a * b)] at h1
    exact h1
  }
exact h
